ALTER TABLE "IndicatorSystem" ADD COLUMN "templateRevision" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "AISuggestion" ADD COLUMN "templateRevision" INTEGER NOT NULL DEFAULT 1;
CREATE TABLE "IndicatorLevelTemplate" (
  "id" TEXT NOT NULL PRIMARY KEY, "systemId" TEXT NOT NULL REFERENCES "IndicatorSystem"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "level" INTEGER NOT NULL CHECK ("level" BETWEEN 1 AND 6), "revisionNo" INTEGER NOT NULL DEFAULT 1, "modules" JSONB NOT NULL
);
CREATE UNIQUE INDEX "IndicatorLevelTemplate_systemId_level_key" ON "IndicatorLevelTemplate"("systemId","level");
CREATE TABLE "IndicatorTemplateRevision" (
  "id" TEXT NOT NULL PRIMARY KEY, "templateId" TEXT NOT NULL REFERENCES "IndicatorLevelTemplate"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "revisionNo" INTEGER NOT NULL, "modules" JSONB NOT NULL, "actorName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX "IndicatorTemplateRevision_templateId_revisionNo_key" ON "IndicatorTemplateRevision"("templateId","revisionNo");
INSERT INTO "IndicatorLevelTemplate" ("id","systemId","level","modules") SELECT md5(id || ':template:1'), id, 1, '[{"moduleKey":"portrait","displayOrder":1,"name":"一级指标概述","researchQuestion":"这个一级指标覆盖什么范围？","fields":[{"fieldId":"level_definition","label":"指标定义","fieldType":"long_text","requirement":"optional"},{"fieldId":"scope_boundary","label":"覆盖范围","fieldType":"long_text","requirement":"optional"},{"fieldId":"overall_goal","label":"总体目标","fieldType":"long_text","requirement":"optional"},{"fieldId":"classification_logic","label":"下级分类逻辑","fieldType":"long_text","requirement":"optional"}]},{"moduleKey":"policy","displayOrder":2,"name":"政策与依据","researchQuestion":"设立该一级指标的主要依据是什么？","fields":[{"fieldId":"policy_basis","label":"政策依据","fieldType":"reference_list","requirement":"optional"},{"fieldId":"strategic_requirements","label":"战略要求","fieldType":"long_text","requirement":"optional"},{"fieldId":"source_notes","label":"来源说明","fieldType":"long_text","requirement":"optional"}]},{"moduleKey":"governance","displayOrder":3,"name":"管理说明","researchQuestion":"该一级指标如何管理和维护？","fields":[{"fieldId":"responsible_department","label":"责任部门","fieldType":"short_text","requirement":"optional"},{"fieldId":"management_mechanism","label":"管理机制","fieldType":"long_text","requirement":"optional"},{"fieldId":"update_cycle","label":"更新周期","fieldType":"short_text","requirement":"optional"}]}]'::jsonb FROM "IndicatorSystem";
