rement":"confirm"},{"fieldId":"priority","label":"轻重缓急","fieldType":"enum","enumValues":["立即整改","分步推进","持续优化"],"requirement":"confirm"}]},{"moduleKey":"optimize","displayOrder":7,"name":"指标优化迭代","researchQuestion":"如何更科学","fields":[{"fieldId":"necessity_assessment","label":"指标必要性评估","fieldType":"long_text","requirement":"confirm","requiresEvidence":true},{"fieldId":"evaluability_assessment","label":"指标可考性判断","fieldType":"long_text","requirement":"confirm","requiresEvidence":true},{"fieldId":"orientation_rationality","label":"指标导向合理性","fieldType":"long_text","requirement":"confirm","requiresEvidence":true},{"fieldId":"differentiated_adjustment","label":"差异化调整","fieldType":"long_text","requirement":"optional","allowNotApplicable":true},{"fieldId":"alternative_proposal","label":"指标替代方案","fieldType":"long_text","requirement":"optional","allowNotApplicable":true},{"fieldId":"grassroots_burden","label":"基层减负考量","fieldType":"long_text","requirement":"confirm"},{"fieldId":"optimization_decision","label":"优化建议","fieldType":"enum","enumValues":["保留","调整","合并","取消","新增"],"requirement":"confirm","requiresEvidence":true}]},{"moduleKey":"contacts","displayOrder":8,"name":"责任单位与联络机制","researchQuestion":"谁来干、如何协同","fields":[{"fieldId":"province_responsibility","label":"省级责任单位","fieldType":"organization_contact_list","requirement":"confirm","requiresEvidence":true},{"fieldId":"city_responsibility","label":"市级责任单位","fieldType":"organization_contact_list","requirement":"confirm","requiresEvidence":true},{"fieldId":"county_responsibility","label":"县级责任单位","fieldType":"organization_contact_list","requirement":"confirm","requiresEvidence":true},{"fieldId":"district_responsibility","label":"市辖区责任单位","fieldType":"organization_contact_list","requirement":"confirm","requiresEvidence":true},{"fieldId":"communication_mechanism","label":"联络与协同机制","fieldType":"long_text","requirement":"publish","allowNotApplicable":true}]}]'::jsonb FROM "IndicatorSystem";
INSERT INTO "IndicatorTemplateRevision" ("id","templateId","revisionNo","modules","actorName") SELECT md5(id || ':1'),id,1,modules,'初始化' FROM "IndicatorLevelTemplate";
-- 历史快照只补模板元数据，不修改原内容及依据标识。
UPDATE "ResearchRevision" r SET snapshot = r.snapshot || jsonb_build_object('templateRevision', 1, 'template', t.modules)
FROM "ResearchModule" m JOIN "ResearchRecord" rec ON rec.id=m."recordId"
JOIN "IndicatorNode" n ON n.id=rec."indicatorNodeId" JOIN "IndicatorVersion" v ON v.id=rec."versionId"
JOIN "IndicatorLevelTemplate" t ON t."systemId"=v."systemId" AND t.level=n.level
WHERE r."moduleId"=m.id AND NOT (r.snapshot ? 'template');

